args.code:
const snapshot = await tools.browser_snapshot({});
const elements = unwrap(snapshot).elements;
const localityInput = elements.find(e => e.name === 'Locality');
if (localityInput) {
  await tools.browser_fill({ref: localityInput.ref, value: '福州'});
}
const newSnapshot = await tools.browser_snapshot({});
const loadButton = newSnapshot.elements.find(e => e.name === 'Load record');
if (loadButton) {
  await tools.browser_click({ref: loadButton.ref});
}
await tools.browser_wait({condition: 'text', value: '鱼丸', timeout_ms: 5000});
return unwrap(await tools.browser_read({}));

